export function getStarsForTime(timeLeft, durationSeconds) {
  if (durationSeconds <= 0) return 1;
  const remaining = timeLeft / durationSeconds;
  if (remaining >= 0.35) return 3;
  if (remaining >= 0.15) return 2;
  return 1;
}
